    val MAP: Map<String, DuaText> = mapOf(
        "dua_undressing" to DuaText("Al quitarse la ropa", "En nombre de Alá.", "Al quitarse la ropa (para ghusl o cambiarse).", "Se convierte en una pantalla entre los ojos de los genios y las partes privadas de una persona."),
        "dua_ilbas_jadidan" to DuaText("Ver a alguien con ropa nueva", "Vístete nuevo, vive dignamente y muere mártir.", "Al ver a un hermano musulmán con ropa nueva.", "El Profeta ﷺ hizo este dua al ver a Umar (RA) con ropa nueva."),
        "dua_hajj_la_riya" to DuaText("Un Hajj libre de alardes", "Oh Allah, (hazlo) un Hajj sin alardes ni búsqueda de fama.", "Por la sinceridad al hacer la intención del Hajj.", "El Profeta ﷺ hizo esta dua en el momento del Hajj."),
        "dua_q_muslimayni_laka" to DuaText("Dua de Ibrahim e Ismail (AS) - Haznos sumisos", "Señor nuestro, haznos sumisos a Ti y de nuestra descendencia una nación sumisa a Ti. Muéstranos nuestros ritos de adoración y acepta nuestro arrepentimiento. De hecho, Tú eres el Aceptador del arrepentimiento, el Misericordioso.", "Un dua de sumisión para uno mismo y sus descendientes.", "La dua realizada durante la construcción de la Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Dua de Shu'aib (AS) - Juez entre nosotros", "Señor nuestro, juzga entre nosotros y nuestro pueblo en verdad, y Tú eres el mejor de los jueces.", "Para un juicio entre la verdad y la falsedad.", "La dua de Shu'ayb (AS) cuando su pueblo lo rechazó."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua de Musa (AS) — Nunca ayuda a los criminales", "Señor mío, gracias al favor que me has concedido, nunca seré ayuda de los malhechores.", "Gratitud por las bendiciones de Allah y compromiso de no ayudar a los malhechores.", "La promesa de Musa (AS) después de su arrepentimiento."),
        "dua_q_nuh_unsurni" to DuaText("Dua de Nuh (AS) — Ayúdame, me lo niegan", "Señor mío, ayúdame, porque me han negado.", "Cuando la gente te niega y rechaza la verdad.", "El dua de Nuh (AS), que fue respondido."),
        "dua_q_ihkum_bil_haqq" to DuaText("Mi Señor, juzga con verdad", "Señor mío, juzga con verdad. Y nuestro Señor es el Misericordioso, cuya ayuda se busca contra lo que usted describe.", "Ante mentiras y acusaciones falsas.", "Una dua enseñada al Profeta ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Refugio de las deudas aplastantes y de los enemigos", "Oh Allah, busco refugio en Ti de ser abrumado por las deudas, de ser dominado por un enemigo y del regodeo de los enemigos.", "Protección contra el peso de la deuda y la dominación de los enemigos.", "El Profeta ﷺ solía buscar refugio de estas cosas."),
        "dua_faqr_qillah_dhillah" to DuaText("Refugio de la pobreza y la humillación", "Oh Allah, busco refugio en Ti de la pobreza, la escasez y la humillación, y de hacer daño a otros o ser agraviado.", "Estar a salvo de las dificultades, las necesidades y la humillación.", "Un refugio enseñado por el Profeta ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Perdona, Ten Misericordia, Guía, Sana, Proporciona", "Oh Allah, perdóname, ten piedad de mí, guíame, concédeme bienestar y mantenme.", "El Profeta ﷺ enseñó esta dua, junto con la oración, a los nuevos musulmanes.", "El Profeta ﷺ dijo: estas palabras reúnen para vosotros este mundo y el Más Allá."),
        "dua_ruku_laka_raka_tu" to DuaText("En Ruku - Ante ti me incliné", "Oh Allah, ante Ti me he inclinado, en Ti he creído y ante Ti me he sometido. Mi oído, mi vista, mi mente, mis huesos y mis tendones se humillan ante Ti.", "En ruku (especialmente en oraciones voluntarias).", "El Profeta ﷺ recitó esto en ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("En Sujood - Ante ti me postré", "Oh Allah, ante Ti me he postrado, en Ti he creído y a Ti me he sometido. Mi rostro se ha postrado ante Aquel que lo creó, le dio forma y le hizo nacer el oído y la vista. Bendito sea Allah, el mejor de los creadores.", "En sujood (especialmente en oraciones voluntarias).", "El Profeta ﷺ recitó esto en suyud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Gloria a Ti, Señor Nuestro – Perdóname", "Gloria a Ti, oh Allah, Señor nuestro, y alabado seas. Oh Allah, perdóname.", "En ruku y sujood.", "Aisha (RA): el Profeta ﷺ solía decir esto en ruku y sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua de Musa (AS) - Perdónanos a mí y a mi hermano", "Señor mío, perdónanos a mí y a mi hermano y admítenos en Tu misericordia, porque Tú eres el Misericordioso de los misericordiosos.", "Perdón para uno mismo y para el hermano o seres queridos.", "La dua de Musa (AS) para Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Encomiendo mis asuntos a Allah", "Y encomiendo mi asunto a Allah. En verdad, Allah es Omnividente con Sus siervos.", "Cuando la gente se opone a ti y el asunto debe dejarse en manos de Allah.", "Las palabras del creyente del pueblo de Faraón; Allah entonces lo protegió de sus malvados complots."),
        "dua_q_hawariyyun" to DuaText("Dua de los discípulos – Regístrenos con los testigos", "Señor nuestro, hemos creído en lo que Tú revelaste y hemos seguido al Mensajero, así que inscríbenos entre los testigos.", "Por la firmeza en la fe y en el seguimiento del Mensajero.", "La dua de los discípulos de Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua de Ibrahim (AS) — No me deshonres", "Y no me avergüences el día en que resucite.", "Estar a salvo de la desgracia en el Día de la Resurrección.", "La dua de Ibrahim (AS) para el Más Allá."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar - Por ti ayuné", "Oh Allah, por Ti he ayunado y con Tu provisión rompo mi ayuno.", "Al romper el ayuno (el conocido iftar dua).", "El Profeta ﷺ dijo esto en el iftar. Es una narración mural potenciada por otras narraciones; recitarlo en iftar es la práctica de los Hanafis y de la mayoría."),
        "dua_iftar_ibn_umar" to DuaText("Iftar – Por tu gran misericordia, perdóname", "Oh Allah, te pido por Tu misericordia que abarca todas las cosas que me perdones.", "En iftar, Abdullah ibn Amr (RA) hizo esta dua; La dua de una persona que ayuna en iftar no se rechaza.", "Hadiz: la dua de la persona que ayuna en el momento del iftar no se rechaza."),
        "dua_inni_saim" to DuaText("Cuando te provocan mientras estás en ayunas", "Estoy ayunando, estoy ayunando.", "Cuando alguien te insulte o riña contigo mientras ayunas.", "El Profeta ﷺ dijo: el ayuno es un escudo, por lo que la persona que ayuna no debe hablar obscenamente ni actuar con ignorancia; si alguien pelea, dígalo dos veces."),
        "dua_eid_takbeer" to DuaText("Takbeer camino al Eid", "Allah es el Más Grande, Allah es el Más Grande, no hay más dios que Allah, y Allah es el Más Grande, Allah es el Más Grande, y toda alabanza es para Allah.", "Desde la noche del avistamiento de la luna hasta la oración del Eid al-Fitr, especialmente en el camino hacia el lugar del Eid.", "El mandamiento coránico: 'para que completes la cuenta y proclames la grandeza de Alá' (al-Baqarah 2:185). Ibn Mas'ud (RA) dijo este takbir."),
        "dua_ahsin_aqibatana" to DuaText("Haz que nuestro fin sea bueno en todos los asuntos", "Oh Allah, haz que nuestro fin sea bueno en todos los asuntos y protégenos de la desgracia en este mundo y del castigo en el Más Allá.", "Para un buen resultado en cada asunto.", "Quien hace esta dua y muere antes de ser juzgado, muere (a salvo del juicio)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Pido tu generosidad y misericordia", "Oh Allah, te pido Tu generosidad y Tu misericordia, porque nadie las posee excepto Tú.", "Al pedir provisión y misericordia.", "Los invitados acudieron al Profeta ﷺ cuando no había comida; Hizo esta dua y luego llegó un regalo."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Palabras enseñadas a un beduino", "Nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado. Allah es el Más Grande, en gran medida; abundantes alabanzas son para Allah; Gloria a Allah, Señor de los mundos; y no hay fuerza ni poder excepto en Allah, el Todopoderoso, el Sabio.", "Una frase completa de dhikr y dua, enseñada a un beduino.", "Después de esto, le enseñaron a decir \"Allahummaghfir li warhamni wahdini warzuqni\"."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Perdona lo que te envié antes y después", "Oh Allah, perdóname los pecados que cometí antes y después, lo que hice en secreto y lo que hice abiertamente, mis excesos y lo que Tú sabes mejor que yo. Tú eres Quien adelanta y Quien pone atrás; no hay más dios que tú.", "Después del tashahhud y salawat, antes del salam.", "El Profeta ﷺ recitó esto al final de la oración, entre el tashahhud y el salam."),
        "dua_jiddi_wa_hazli" to DuaText("Perdona mi seriedad y mi broma", "Oh Allah, perdóname los pecados que cometí en serio y en broma, por error y deliberadamente, y todo eso está en mí.", "Perdón por todo tipo de pecado, conocido y desconocido.", "Un istighfar completo del Profeta ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Después de Ruku: la alabanza llena los cielos", "Señor nuestro, a Ti pertenece toda alabanza, llenando los cielos, llenando la tierra y llenando todo lo que Tú quieras después de eso.", "Después de surgir del ruku, junto con 'Rabbana lakal-hamd'.", "El Profeta ﷺ dijo esto al levantarse del ruku."),
        "dua_istiftah_kabira" to DuaText("Allah es el más grande y abundantemente alabado", "Allah es el Más Grande, en gran medida; abundantes alabanzas son para Allah; y gloria a Allah mañana y tarde.", "Al comenzar la oración (una forma de alabanza inicial).", "El Profeta ﷺ dijo: las puertas del cielo le fueron abiertas."),
        "dua_q_ashku_bathhi" to DuaText("Dua de Yaqub (AS) — Sólo me quejo ante Allah", "Me quejo de mi angustia y mi pena sólo ante Allah.", "En profundo dolor y separación.", "Ya'qub (AS) dijo esto en su separación de Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah es el mejor protector", "Allah es el mejor Protector y el Más Misericordioso entre los misericordiosos.", "Al enviar a niños o seres queridos de viaje.", "Ya'qub (AS) dijo esto mientras confiaba a su hijo a Allah."),
        "dua_q_aqraba_rashada" to DuaText("Que mi Señor me guíe más cerca de lo correcto", "Quizás mi Señor me guíe hacia lo que está más cerca de esto de la conducta correcta.", "Al buscar una mejor manera en algún asunto.", "Al Profeta ﷺ se le dijo que dijera esto al olvidarlo."),
        "dua_q_sawa_as_sabil" to DuaText("Dua de Musa (AS) - Guíame por el camino correcto", "Quizás mi Señor me guíe por el camino correcto.", "Al emprender un nuevo viaje o un camino desconocido.", "Musa (AS) dijo esto mientras se volvía hacia Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("No me pongáis entre los malhechores", "Señor mío, no me pongas entre la gente malhechora.", "Una dua que pide a Allah que nos mantenga alejados de los malhechores.", "Una dua que pide a Allah que nos mantenga alejados de los malhechores."),
        "dua_q_do_not_make_us_trial" to DuaText("No nos hagas una prueba", "Señor nuestro, no nos hagas prueba para los incrédulos, y perdónanos, Señor nuestro. De hecho, Tú eres el Todopoderoso, el Sabio.", "La dua de Ibrahim (AS) y sus compañeros.", "La dua de Ibrahim (AS) y sus compañeros."),
        "dua_morning_witness" to DuaText("Testimonio matutino del Tawhid", "Oh Allah, he entrado en la mañana invocándote a Ti, a los portadores de Tu Trono, a Tus ángeles y a toda Tu creación para que sean testigos que Tú eres Allah, que no hay dios excepto Tú, solo, sin asociado, y que Muhammad ﷺ es Tu siervo y Mensajero.", "La narración menciona decirlo cuatro veces por la mañana.", "La narración menciona decirlo cuatro veces por la mañana."),
        "dua_evening_witness" to DuaText("Testimonio vespertino del Tawhid", "Oh Allah, he entrado en la noche invocándote a Ti, a los portadores de Tu Trono, a Tus ángeles y a toda Tu creación para que sean testigos que Tú eres Allah, que no hay más dios que Tú, solo, sin asociado, y que Muhammad ﷺ es Tu siervo y Mensajero.", "La narración menciona decirlo cuatro veces por la noche.", "La narración menciona decirlo cuatro veces por la noche."),
        "dua_morning_blessing" to DuaText("Buenos dias gracias por las bendiciones", "Oh Allah, cualquier bendición que yo o cualquiera de Tu creación haya recibido esta mañana proviene únicamente de Ti, sin asociado; por eso a Ti pertenece toda alabanza y todo agradecimiento.", "Dhikr matutino de gratitud por las bendiciones de Allah.", "Dhikr matutino de gratitud por las bendiciones de Allah."),
        "dua_evening_blessing" to DuaText("Tarde Gracias por Bendiciones", "Oh Allah, cualquier bendición que yo o cualquiera de Tu creación haya recibido esta noche proviene únicamente de Ti, sin asociado; por eso a Ti pertenece toda alabanza y todo agradecimiento.", "Dhikr vespertino de gratitud por las bendiciones de Allah.", "Dhikr vespertino de gratitud por las bendiciones de Allah."),
